    },
    {
      "year": 2042,
      "event": "First permanent Mars colony established.",
      "detail": "A self-sustaining settlement of 100+ people begins continuous habitation on Mars, though remains dependent on Earth supplies for complex equipment."
    },
    {
      "year": 2055,
      "event": "Global population peaks at 9.7 billion.",
      "detail": "Fertility rates have fallen below replacement in most countries. Aging demographics strain social systems worldwide."
    },
    {
      "year": 2063,
      "event": "AI systems control majority of economic decisions.",
      "detail": "Superintelligent AI manages supply chains, financial markets, and resource allocation. Human economic roles shift primarily to creative and interpersonal work."
    },
    {
      "year": 2071,
      "event": "Average global temperature reaches +2.8°C above pre-industrial levels.",
