    },
    {
      "year": 2098,
      "event": "Gene-edited humans comprise 15% of births.",
      "detail": "Designer babies with enhanced intelligence, disease resistance, and longevity become common among wealthy populations, creating new forms of inequality."
    },
    {
      "year": 2115,
      "event": "Fusion power provides 70% of global energy.",
      "detail": "Cheap, abundant fusion finally replaces fossil fuels, but comes too late to prevent 3.5°C warming and massive ecosystem collapses."
    },
    {
      "year": 2142,
      "event": "First self-sustaining space habitat completed.",
      "detail": "O'Neill cylinder in Earth-Moon L5 houses 50,000 people with closed-loop life support and manufacturing capability."
    },
    {
      "year": 2178,
      "event": "Biological humans become minority of sentient population.",
      "detail": "Digital minds and AI entities outnumber biological humans 3:1. Most humans have some cybernetic augmentation."
    },
    {
      "year": 2215,
      "event": "Antarctic ice sheet collapse completes.",
      "detail": "Sea levels have risen 12 meters total. Major coastal cities abandoned. 2 billion climate refugees have resettled over the past century."
    },
    {
      "year": 2284,
      "event": "First interstellar probe reaches Proxima Centauri.",
      "detail": "Unmanned craft traveling at 15% light speed arrives after 30-year journey, confirming potentially habitable exoplanet."
    },
    {
      "year": 2340,
      "event": "Earth's human population drops below 2 billion.",
      "detail": "Combination of environmental degradation, voluntary population reduction, and migration to space habitats. Most humans heavily modified or uploaded."
    },
    {
      "year": 2405,
      "event": "Nanotechnology enables matter programmability.",
      "detail": "Molecular assemblers can reconfigure matter at will, effectively ending material scarcity for those with access to the technology and energy."
