    },
    {
      "year": 2680,
      "event": "First generation ship launched to another star.",
      "detail": "10,000 volunteers depart for 300-year journey to habitable exoplanet. Mix of biological, enhanced, and digital passengers."
    },
    {
      "year": 2850,
      "event": "Earth declared a historical preserve.",
      "detail": "Planet's ecosystem being restored after centuries of damage. Only 50 million inhabitants, mostly researchers and caretakers."
    },
    {
      "year": 3100,
      "event": "Human descendants diverge into distinct species.",
      "detail": "Genetic, cybernetic, and digital lineages no longer interbreed. Classical homo sapiens comprises less than 1% of human-descended intelligence."
    },
    {
      "year": 3400,
      "event": "Dyson swarm construction begins around Sun.",
      "detail": "Massive energy collection structure to power expanding civilization and support billions of uploaded minds running at accelerated speeds."
